use serde_json::{json,Value};
fn schema(name:&str,description:&str,fields:&[(&str,&str,&[&str],&str)],required:&[&str])->Value{let mut properties=serde_json::Map::new();for(k,t,values,desc)in fields{let mut p=serde_json::Map::new();p.insert("type".into(),json!(t));p.insert("description".into(),json!(desc));if !values.is_empty(){p.insert("enum".into(),json!(values));}properties.insert(k.to_string(),Value::Object(p));}json!({"type":"function","function":{"name":name,"description":description,"parameters":{"type":"object","properties":properties,"required":required,"additionalProperties":false}}})}
pub fn validate(name:&str,args:&Value)->Result<(),String>{if let Some(schema)=catalog().into_iter().find(|s|s["function"]["name"]==name){let p=&schema["function"]["parameters"];let o=args.as_object().ok_or("arguments must be object")?;for k in p["required"].as_array().unwrap(){let k=k.as_str().unwrap();if !o.contains_key(k){return Err(format!("Missing argument: {k}"));}}for(k,v)in o{let prop=&p["properties"][k];let valid=match prop["type"].as_str(){Some("string")=>v.is_string(),Some("integer")=>v.is_u64(),Some("boolean")=>v.is_boolean(),Some("array")=>v.is_array(),_=>false};if !valid{return Err(format!("Unsupported argument or incorrect type: {k}"));}if let Some(values)=prop.get("enum").and_then(Value::as_array){if !values.contains(v){return Err(format!("Unsupported value for {k}: {v}"));}}}Ok(())}else{Ok(())}}
fn process()->Value{schema("process","Manage background jobs started on this SSH connection only. Actions: list, status (does not consume output), poll (consume new output and status), wait, kill, write (raw stdin), submit (stdin plus newline); no PTY support",&[("action","string",&["list","status","poll","wait","kill","write","submit"],"Management action"),("session_id","string",&[],"Background session from terminal background=true (required except list)"),("timeout","integer",&[],"wait timeout seconds (1..=1800, default 30)"),("data","string",&[],"Raw bytes to write; mutually exclusive with text"),("text","string",&[],"Same as data for compatibility")],&["action"])}
pub fn catalog()->Vec<Value>{vec![
 schema("read_file","Read UTF-8 text with line numbers. No PDF/Office/image extraction; use file_get for binary",&[("path","string",&[],"Absolute, ~-relative or cwd-relative regular file"),("offset","integer",&[],"1-indexed first line (default 1)"),("limit","integer",&[],"Maximum lines, at most 2000 (default 2000)")],&["path"]),
 schema("write_file","Write UTF-8 text, creating or truncating a regular file. Refuses symlinks and non-regular files",&[("path","string",&[],"Regular non-symlink path"),("content","string",&[],"UTF-8 content, at most 8 MiB")],&["path","content"]),
 schema("patch","Replace exact literal text. Fails unless the match is unique unless replace_all is true. Nothing is written on failure",&[("path","string",&[],"UTF-8 regular file"),("old_string","string",&[],"Nonempty literal to replace"),("new_string","string",&[],"Replacement literal, different from old_string"),("replace_all","boolean",&[],"Replace every occurrence (default false)")],&["path","old_string","new_string"]),
 schema("search_files","Search UTF-8 file contents with Rust regex syntax or file names with * and ? globs. Binary files are skipped and listed under skipped. Symlinks are not traversed. Bounded: 100000 entries, 512 MiB scanned, 100000 matches, 1000 returned",&[("pattern","string",&[],"Regex for content, glob for target=files"),("target","string",&["content","files"],"content or files (default content)"),("path","string",&[],"Root file or directory (default current directory)"),("file_glob","string",&[],"Filename glob filter for content search"),("limit","integer",&[],"Results returned, at most 1000 (default 50)"),("offset","integer",&[],"Skip this many results"),("order","string",&["discovery"],"Only deterministic discovery order is supported"),("output_mode","string",&["content","files_only","count"],"Result shape"),("context","integer",&[],"Context lines before/after, at most 50")],&["pattern"]),
 schema("terminal","Run a command in persistent real bash. Working directory and exported shell variables carry over between calls on this connection. Runs non-interactively with stdin from /dev/null; background=true detaches stdout/stderr into a manageable job. No PTY, notification hooks or Hermes approval guards; authority is the SSH account",&[("command","string",&[],"Bash command; may be multiline"),("workdir","string",&[],"Only supported with background=true; foreground workdir is rejected. Use explicit cd in a foreground command (persists in shell), or background workdir. Relative paths are resolved against receiver cwd"),("timeout","integer",&[],"Seconds 1..=1800 (default 180). On expiry the whole process group is SIGKILLed and the shell is reset"),("background","boolean",&[],"Start a detached job and return session_id/pid"),("pty","boolean",&[],"Must be false; a PTY is not implemented")],&["command"]),
 process(),
 process(),
 schema("skills_list","List SKILL.md directories found under $TELEOPERATOR_HOME/skills plus ~/.hermes/skills when that directory exists. Filesystem only; requires no Hermes installation",&[("category","string",&[],"Optional relative category prefix filter")],&[]),
 schema("skill_view","Read a SKILL.md or one supporting file from an installed skill. Symlinks are refused",&[("name","string",&[],"Skill directory name"),("file_path","string",&[],"references/, templates/, scripts/ or assets/ relative file")],&["name"]),
 schema("skill_manage","Apply create, patch, write_file or remove_file operations under $TELEOPERATOR_HOME/skills only. Input is {operations:[...]}. All operations are validated and staged before any write; failures roll back. Delete and full replacement are unavailable; read-only ~/.hermes/skills fallback cannot be managed",&[("operations","array",&[],"1..100 operation objects with action and name")],&["operations"])
]}
